'use strict';
const state=Workspace.snapshot().draft;
let currentPage='home',currentMode='analysis',lastPoint=null,editingIndex=-1,routeAnalyzed=false,libraryTab='routes',toastTimer=null,undoAction=null,storageWarningShown=false;
const maps={analysis:null,route:null},tiles={analysis:null,route:null},mapStyles={analysis:'ocean',route:'ocean'};
let analysisMarker=null,routeGroup=null;
let plannedRoute=null,routePlanning=false,routeGeneration=0,routeState="idle",routeErrorPoint=null;
const rt=key=>window.WARouteText?window.WARouteText(key):key;
function routeDisplayCoordinates(){if(!plannedRoute)return [];const output=[];let previous=null;for(const [x,y]of plannedRoute.coordinates){let lon=x;if(previous!==null){while(lon-previous>180)lon-=360;while(lon-previous< -180)lon+=360;}output.push([y,lon]);previous=lon;}return output;}
const CENTER=[-64.8,-63.9];
const RISK={normal:{label:'Normal seyir',color:'#438b76',text:'Klorofil-a oranı risk eşiklerinin altında. Bölgesel izleme ve standart seyir değerlendirmesini sürdürün.'},moderate:{label:'Orta risk',color:'#b18b46',text:'Klorofil-a oranı klasik modelin orta risk eşiğinde. Bu sınıf, gözlenmiş balina konumu veya türlere özgü habitat tahmini değildir.'},critical:{label:'Kritik risk',color:'#d06a5d',text:'Klorofil-a oranı klasik modelin kritik eşiğinde. Bu sınıf, doğrulanmış çarpışma olasılığı değildir.'}};
const escapeText=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stamp=value=>new Date(value).toLocaleString(I18n.locale,{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
const pointCopy=()=>state.points.map(p=>({lat:p.lat,lon:p.lon,klor:p.klor}));
const riskBadge=level=>`<span class="risk-badge ${level}">${RISK[level].label}</span>`;
function notify(message,action=null){clearTimeout(toastTimer);$('toastText').textContent=message;$('toastAction').hidden=!action;undoAction=action;$('toast').hidden=false;toastTimer=setTimeout(()=>{$('toast').hidden=true;undoAction=null;},action?9000:4500);}
function persist(){const ok=Workspace.setDraft(state);window.dispatchEvent(new CustomEvent('walerter:routechange',{detail:{...Workspace.snapshot().draft,computedRoute:plannedRoute}}));$('draftStatus').innerHTML=ok?'<i></i>Bu tarayıcıda kaydedildi':'Kaydedilemedi';if(!ok&&!storageWarningShown){storageWarningShown=true;notify('Bu tarayıcı taslağı kaydedemiyor. Rotanızı JSON olarak yedekleyin.');}if(ok)storageWarningShown=false;$('draftStatus').title=ok?'Son taslağınız bu tarayıcıda saklanıyor.':'Tarayıcı depolaması kullanılamıyor. JSON olarak dışa aktarın.';}
function go(page){if(location.hash!==`#${page}`)location.hash=page;showPage(page);}
function showPage(raw){if(raw==='main')return;const page=raw==='workflow'?'home':raw==='about'?'home':['analysis','route','library','archive','home','data','ocean','species','hydra','fuel','voyage'].includes(raw)?raw:'home';currentPage=page;document.body.dataset.page=page;const workspace=page==='analysis'||page==='route';document.body.classList.toggle('is-workspace',page!=='home');document.querySelectorAll('.screen').forEach(el=>el.hidden=el.id!==(workspace?'page-workspace':`page-${page}`));document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(page==='home'?'home':'workspace');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('mainNav').classList.remove('open');$('mobileMenuButton').setAttribute('aria-expanded','false');const title={home:'Deniz ekosistemi için rota analizi',analysis:'Konum analizi',route:'Rota planlayıcı',library:'Kayıtlarım',archive:'Veri & yöntem',data:'Veri merkezi',ocean:'Kuzey Atlantik',species:'Tür modelleri',hydra:'HYDRA 2.0',fuel:'Yakıt & karbon',voyage:'Sefer karşılaştırması'};document.title=`${title[page]} — W-ALERTER`;
if(workspace){currentMode=page;$('mapLegend').innerHTML=page==='route'?'<span data-user-content><i class="legend-dot normal"></i>Chl-a &lt; 1.25×</span><span data-user-content><i class="legend-dot critical"></i>Chl-a ≥ 1.25×</span>':'<span><i class="legend-dot normal"></i>Normal</span><span><i class="legend-dot moderate"></i>Orta risk</span><span><i class="legend-dot critical"></i>Kritik risk</span>';$('workspaceHeading').innerHTML=page==='analysis'?'Risk analizi':'Sefer planlama';$('analysisInspector').hidden=page!=='analysis';$('routeInspector').hidden=page!=='route';$('analysisMap').hidden=page!=='analysis';$('routeMap').hidden=page!=='route';$('recentObservations').hidden=page!=='analysis';$('routeOutput').hidden=page!=='route'||!routeAnalyzed;document.querySelectorAll('[data-mode]').forEach(a=>{const active=a.dataset.mode===page;a.classList.toggle('active',active);a.setAttribute('aria-current',active?'page':'false');});initMap(page);if(maps[page])requestAnimationFrame(()=>maps[page].invalidateSize());refreshLayers();$('floatingResult').hidden=page!=='analysis'||!lastPoint;$('mapSelectionText').textContent=page==='analysis'?'Haritaya tıklayarak konum seçin':'Konum seçin · Geçiş noktalarını sürükleyerek taşıyın';}
window.dispatchEvent(new CustomEvent('walerter:pagechange',{detail:{page}}));if(page==='home')initHomeMap();if(page==='library')renderLibrary();if(raw==='workflow')requestAnimationFrame(()=>$('workflow').scrollIntoView());else window.scrollTo({top:0,behavior:'instant'});}
function coordinates(lat,lon){return `${Math.abs(lat).toFixed(4)}° ${lat<0?'G':'K'} / ${Math.abs(lon).toFixed(4)}° ${lon<0?'B':'D'}`;}
function makeLayer(style){if(style==='ocean')return L.layerGroup([L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Ocean/World_Ocean_Base/MapServer/tile/{z}/{y}/{x}',{maxZoom:13,attribution:'Tiles © Esri, GEBCO, NOAA'}),L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Ocean/World_Ocean_Reference/MapServer/tile/{z}/{y}/{x}',{maxZoom:13,attribution:'Esri Ocean Reference'})]);return L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'});}
function setMapLayer(mode,style){if(!maps[mode])return;if(tiles[mode])maps[mode].removeLayer(tiles[mode]);mapStyles[mode]=style;const layer=makeLayer(style);let failed=0;(layer instanceof L.LayerGroup?layer.getLayers():[layer]).forEach(l=>{l.on('tileerror',()=>{if(++failed>=4&&currentMode===mode){$('mapError').textContent='Harita katmanı yüklenemiyor. Diğer katmanı deneyebilir veya koordinat girerek çalışabilirsiniz.';$('mapError').hidden=false;}});l.on('tileload',()=>{failed=0;$('mapError').hidden=true;});});tiles[mode]=layer.addTo(maps[mode]);refreshLayers();}
function refreshLayers(){document.querySelectorAll('[data-layer]').forEach(b=>{const active=b.dataset.layer===mapStyles[currentMode];b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
function initMap(mode){if(maps[mode])return;if(!window.L){$('mapError').textContent='Harita yüklenemedi. Koordinat girerek çalışmaya devam edebilirsiniz.';$('mapError').hidden=false;return;}const map=L.map(`${mode}Map`,{zoomControl:false,scrollWheelZoom:true}).setView(CENTER,6);maps[mode]=map;setMapLayer(mode,mapStyles[mode]);map.on('mousemove',e=>{$('mapCoordinates').textContent=coordinates(e.latlng.lat,e.latlng.lng);});map.on('click',e=>{const prefix=mode==='analysis'?'analysis':'stop';$(prefix+'Lat').value=e.latlng.lat.toFixed(5);$(prefix+'Lon').value=e.latlng.lng.toFixed(5);$('mapCoordinates').textContent=coordinates(e.latlng.lat,e.latlng.lng);if(mode==='analysis'){invalidateAnalysis();if(analysisMarker)map.removeLayer(analysisMarker);analysisMarker=L.circleMarker(e.latlng,{radius:7,color:'#fff',weight:3,fillColor:'#f47e65',fillOpacity:1}).addTo(map);}else notify('Konum seçildi. Klorofil-a ölçümünü girerek noktayı ekleyin.');});if(mode==='route'){routeGroup=L.layerGroup().addTo(map);syncRouteMap();}}
function updateReference(){const month=$('analysisMonth').value;$('analysisReference').innerHTML=`${ARSIV[month].toFixed(4)} <small>mg/m³</small>`;}
function invalidateAnalysis(){lastPoint=null;$('analysisResult').hidden=true;$('analysisEmpty').hidden=false;$('floatingResult').hidden=true;if(analysisMarker&&maps.analysis){maps.analysis.removeLayer(analysisMarker);analysisMarker=null;}}
function displayAnalysis(point,saveHistory=false,fly=true){const result=pointModel(point.month,point.klor),risk=RISK[result.level];lastPoint={...point};$('analysisResult').hidden=false;$('analysisEmpty').hidden=true;$('analysisResult').dataset.level=result.level;$('resultBadge').className=`risk-badge ${result.level}`;$('resultBadge').textContent=risk.label;$('resultRate').textContent=result.rate;$('resultRatio').textContent=result.ratio.toFixed(2)+'×';$('resultMeasurement').textContent=point.klor+' mg/m³';$('resultReference').textContent=result.reference.toFixed(4)+' mg/m³';$('resultDescription').textContent=risk.text;$('floatingResult').hidden=currentPage!=='analysis';$('floatingResultStatus').textContent=risk.label;$('floatingResultStatus').style.color=risk.color;$('floatingResultCoords').textContent=`${point.lat.toFixed(4)} / ${point.lon.toFixed(4)}`;$('floatingResultMonth').textContent=`${point.month} · ${point.klor} mg/m³`;
if(saveHistory){if(!Workspace.addObservation(point))notify('Gözlem hesaplandı; bu tarayıcı geçmişi kaydedemiyor.');renderRecent();updateCounts();}
if(maps.analysis){if(analysisMarker)maps.analysis.removeLayer(analysisMarker);analysisMarker=L.circleMarker([point.lat,point.lon],{radius:11,color:'#fff',weight:3,fillColor:risk.color,fillOpacity:1}).addTo(maps.analysis);analysisMarker.bindTooltip(`${risk.label} · ${point.klor} mg/m³`);if(fly)maps.analysis.flyTo([point.lat,point.lon],9,{duration:.65,animate:!matchMedia('(prefers-reduced-motion: reduce)').matches});}}
function analyzePoint(e){e.preventDefault();if(!$('analysisForm').reportValidity())return;const point={month:$('analysisMonth').value,lat:parseFloat($('analysisLat').value),lon:parseFloat($('analysisLon').value),klor:parseFloat($('analysisChlo').value)};if(!Workspace.validPoint(point))return;displayAnalysis(point,true);if(innerWidth<=620)$('analysisResult').scrollIntoView({block:'start',behavior:'smooth'});else $('analysisResult').scrollIntoView({block:'nearest',behavior:'smooth'});}
function renderRoute(){const count=state.points.length;$('pointCount').textContent=count;$('clearRouteButton').disabled=!count;$('analyzeRouteButton').disabled=count<2||routePlanning;$('analyzeRouteButton').innerHTML=escapeText(rt(routePlanning?'loading':'calculate'))+icon('arrow');if($('routeTopologyStatus')){$('routeTopologyStatus').dataset.state=routeState;$('routeTopologyStatus').textContent=rt(routeState)+(routeErrorPoint==null?'':' · '+I18n.translate('Nokta '+(routeErrorPoint+1)));}$('saveRouteButton').disabled=count<2;$('routeName').value=state.name==='İsimsiz sefer'?'':state.name;$('routeMonth').value=state.month;
$('routeList').innerHTML=count?state.points.map((p,i)=>{const risky=routePointStatus(state.month,p.klor)==='RISKLI';return `<div class="point-item" ${i===editingIndex?'aria-current="true"':''}><span class="point-index">${String(i+1).padStart(2,'0')}</span><div class="point-info"><strong>${p.lat.toFixed(3)} / ${p.lon.toFixed(3)}</strong><span><i class="point-risk-dot ${risky?'risky':''}"></i>${p.klor} mg/m³ · ${risky?'Chl-a ≥ 1.25×':'Chl-a < 1.25×'}</span></div><div class="point-actions"><div class="reorder-buttons"><button class="icon-btn" data-point-action="up" data-index="${i}" aria-label="${i+1}. noktayı yukarı taşı" ${i===0?'disabled':''}>${icon('up')}</button><button class="icon-btn" data-point-action="down" data-index="${i}" aria-label="${i+1}. noktayı aşağı taşı" ${i===count-1?'disabled':''}>${icon('down')}</button></div><button class="icon-btn" data-point-action="edit" data-index="${i}" aria-label="${i+1}. noktayı düzenle">${icon('edit')}</button><button class="icon-btn delete-point" data-point-action="delete" data-index="${i}" aria-label="${i+1}. noktayı sil">${icon('close')}</button></div></div>`;}).join(''):`<div class="point-empty"><span data-icon="route">${icon('route')}</span><p>İki geçiş noktasıyla başlayın.</p></div>`;
}
function cancelPointEdit(){editingIndex=-1;$('routeForm').reset();$('pointFormTitle').textContent='Geçiş noktası ekle';$('addPointButton').innerHTML=icon('plus')+'Noktayı ekle';$('cancelEdit').hidden=true;}
function routeChanged(){++routeGeneration;window.WARouting?.cancel();plannedRoute=null;routeAnalyzed=false;routePlanning=false;routeState='idle';routeErrorPoint=null;$('routeOutput').hidden=true;renderRoute();persist();syncRouteMap();}
function submitPoint(e){e.preventDefault();if(!$('routeForm').reportValidity())return;const point={lat:parseFloat($('stopLat').value),lon:parseFloat($('stopLon').value),klor:parseFloat($('stopChlo').value)};if(!Workspace.validPoint(point))return;if(editingIndex>=0)state.points[editingIndex]=point;else{if(state.points.length>=1000){notify('Bir sefer en fazla 1000 geçiş noktası içerebilir.');return;}state.points.push(point);}cancelPointEdit();routeChanged();if(state.points.length===1&&maps.route)maps.route.setView([point.lat,point.lon],7);}
function pointAction(action,index){if(!state.points[index])return;if(action==='edit'){const p=state.points[index];editingIndex=index;$('stopLat').value=p.lat;$('stopLon').value=p.lon;$('stopChlo').value=p.klor;$('pointFormTitle').textContent=`${index+1}. noktayı düzenle`;$('addPointButton').innerHTML=icon('check')+'Değişiklikleri uygula';$('cancelEdit').hidden=false;renderRoute();$('routeForm').scrollIntoView({block:'nearest',behavior:'smooth'});return;}
const previous=pointCopy();if(action==='delete')state.points.splice(index,1);if(action==='up'&&index>0)[state.points[index-1],state.points[index]]=[state.points[index],state.points[index-1]];if(action==='down'&&index<state.points.length-1)[state.points[index+1],state.points[index]]=[state.points[index],state.points[index+1]];cancelPointEdit();routeChanged();if(action==='delete')notify('Geçiş noktası kaldırıldı.',()=>{state.points=previous;routeChanged();});}
function syncRouteMap(){if(!routeGroup||!maps.route)return;routeGroup.clearLayers();const anchor=state.points[0]?.lon??0;state.points.forEach((p,i)=>{const risky=routePointStatus(state.month,p.klor)==='RISKLI';let lon=p.lon;while(lon-anchor>180)lon-=360;while(lon-anchor< -180)lon+=360;const m=L.marker([p.lat,lon],{draggable:true,autoPan:true,title:`Geçiş noktası ${i+1}`,icon:L.divIcon({className:'route-marker-wrap',html:`<span class="route-marker ${risky?'risky':''}">${i+1}</span>`,iconSize:[27,27],iconAnchor:[13,13]})}).addTo(routeGroup);m.bindTooltip(`Nokta ${i+1} · ${p.klor} mg/m³`);m.on('dragend',()=>{const pos=m.getLatLng();if(Math.abs(pos.lat)>90||!Number.isFinite(pos.lng)){m.setLatLng([p.lat,lon]);notify('Geçerli koordinat aralığında bir konum seçin.');return;}p.lat=pos.lat;p.lon=((pos.lng+180)%360+360)%360-180;routeChanged();});});if(routeAnalyzed&&plannedRoute){const line=L.polyline(routeDisplayCoordinates(),{color:'#216f78',weight:3.5,opacity:.95,smoothFactor:0});line.bindTooltip(rt('engine'));line.addTo(routeGroup);}}
function fitMap(){const map=maps[currentMode];if(!map)return;if(currentMode==='route'&&plannedRoute)map.fitBounds(L.latLngBounds(routeDisplayCoordinates()),{padding:[70,70],maxZoom:9});else if(currentMode==='route'&&state.points.length>1)map.fitBounds(L.latLngBounds(state.points.map(p=>[p.lat,p.lon])),{padding:[70,70],maxZoom:9});else if(currentMode==='analysis'&&lastPoint)map.setView([lastPoint.lat,lastPoint.lon],9);else map.setView(CENTER,6);}
function renderRouteOutput(){if(!plannedRoute||state.points.length<2)return;const result=plannedRoute,stats=$('routeOutput').querySelector('.route-stats');stats.dataset.userContent='';const cells=stats.querySelectorAll(':scope>div');for(const [i,key]of ['distance','direct','detour','topology'].entries())cells[i].querySelector('span').textContent=rt(key);$('totalNM').innerHTML=result.totalNM.toFixed(2)+'<small>NM</small>';$('riskNM').innerHTML=result.directNM.toFixed(2)+'<small>NM</small>';$('riskNM').classList.remove('coral-text');$('fuelSaving').innerHTML=(result.totalNM-result.directNM).toFixed(2)+'<small>NM</small>';cells[3].innerHTML='<span>'+escapeText(rt('topology'))+'</span><strong>0.1<small>°</small></strong><small>Natural Earth · A* · 16</small>';$('segmentRows').dataset.userContent='';$('segmentRows').innerHTML=result.legs.map((leg,i)=>{const p=state.points[i+1];return `<tr><td>${String(i+1).padStart(2,'0')} → ${String(i+2).padStart(2,'0')}</td><td class="mono">${p.lat.toFixed(4)} / ${p.lon.toFixed(4)}</td><td>${p.klor} mg/m³</td><td class="mono">${leg.distanceNM.toFixed(2)} NM</td><td><span class="risk-badge normal">${escapeText(rt('leg'))}</span></td></tr>`;}).join('');const note=$('routeOutput').querySelector('.output-note');note.dataset.userContent='';note.textContent=rt('limit')+' '+rt('biology');$('routeOutput').hidden=currentPage!=='route';}
async function analyzeRoute(){if(state.points.length<2)return;const generation=++routeGeneration;plannedRoute=null;routeAnalyzed=false;routePlanning=true;routeState='loading';routeErrorPoint=null;$('routeOutput').hidden=true;syncRouteMap();renderRoute();try{if(!window.WARouting)throw Error('routing_unavailable');const result=await window.WARouting.plan(pointCopy());if(generation!==routeGeneration)return;if(result.status!=='found'){routeState=['blocked_waypoint','outside_topology','no_path','search_limit','invalid_waypoint_count','duplicate_waypoints'].includes(result.status)?result.status:'error';routeErrorPoint=result.pointIndex??null;notify(rt(routeState));return;}plannedRoute=result;routeAnalyzed=true;routeState='found';renderRouteOutput();syncRouteMap();fitMap();window.dispatchEvent(new CustomEvent('walerter:routeplanned',{detail:{...Workspace.snapshot().draft,computedRoute:result}}));notify(rt('found'));}catch(error){if(generation===routeGeneration){routeState='error';notify(rt('error'));}}finally{if(generation===routeGeneration){routePlanning=false;renderRoute();}}}
function loadRoute(route,routeId=null){state.name=route.name;state.month=route.month;state.points=route.points.map(p=>({...p}));state.routeId=routeId;routeAnalyzed=false;cancelPointEdit();routeChanged();go('route');initMap('route');syncRouteMap();if(state.points.length>=2)analyzeRoute();}
function reopenObservation(id){const p=Workspace.snapshot().observations.find(o=>o.id===id);if(!p)return;go('analysis');$('analysisMonth').value=p.month;$('analysisLat').value=p.lat;$('analysisLon').value=p.lon;$('analysisChlo').value=p.klor;updateReference();displayAnalysis(p,false);}
function updateCounts(){const d=Workspace.snapshot();$('savedCount').textContent=d.routes.length;$('routesCount').textContent=d.routes.length;$('observationsCount').textContent=d.observations.length;}
function renderRecent(){const items=Workspace.snapshot().observations.slice(0,3);$('recentObservationRows').innerHTML=items.length?`<div class="recent-grid">${items.map(p=>{const level=pointModel(p.month,p.klor).level;return `<article class="recent-item"><div><strong>${p.lat.toFixed(3)} / ${p.lon.toFixed(3)}</strong>${riskBadge(level)}</div><p>${p.month} · ${p.klor} mg/m³</p><small>${stamp(p.createdAt)}</small><button data-observation="${escapeText(p.id)}">Gözlemi aç ${icon('arrow')}</button></article>`;}).join('')}</div>`:`<div class="recent-empty"><span>${icon('radar')}Gözlem geçmişiniz ilk analizle oluşacak.</span><small>Verileriniz bu tarayıcıda saklanır.</small></div>`;}
function routePreview(points){const lats=points.map(p=>p.lat),lons=points.map(p=>p.lon),minLat=Math.min(...lats),minLon=Math.min(...lons),dy=Math.max(...lats)-minLat||1,dx=Math.max(...lons)-minLon||1;const coords=points.map(p=>[15+(p.lon-minLon)/dx*170,85-(p.lat-minLat)/dy*70]);return `<svg class="route-preview" viewBox="0 0 200 100" preserveAspectRatio="xMidYMid meet" aria-label="Geçiş noktası taslağı"><polyline points="${coords.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#6ba5b4" stroke-width="1.5" stroke-dasharray="4 4"/>${coords.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3" fill="#207f93" stroke="#eff5f8" stroke-width="1.5"/>`).join('')}</svg>`;}
function renderLibrary(){updateCounts();$('exportHistoryButton').hidden=libraryTab!=='observations';document.querySelectorAll('[data-library-tab]').forEach(b=>b.classList.toggle('active',b.dataset.libraryTab===libraryTab));const d=Workspace.snapshot(),query=$('librarySearch').value.toLocaleLowerCase(I18n.locale).trim();if(libraryTab==='routes'){const routes=d.routes.filter(r=>(r.name+' '+r.month+' '+I18n.translate(r.month)).toLocaleLowerCase(I18n.locale).includes(query));$('libraryContents').innerHTML=routes.length?`<div class="saved-route-grid">${routes.map(r=>{const result=routeModel(r.points,r.month);return `<article class="saved-route-card"><div class="route-card-visual"><span>${escapeText(r.month.toLocaleUpperCase('tr-TR'))} / ANTARKTİKA</span>${routePreview(r.points)}<button class="icon-btn" data-delete-route="${escapeText(r.id)}" data-user-content aria-label="${escapeText(r.name)} ${I18n.translate('seferini sil')}">${icon('trash')}</button></div><div class="route-card-content"><h2 data-user-content>${escapeText(r.name)}</h2><p>Son kayıt · ${stamp(r.savedAt)}</p><div class="route-card-stats"><span>GEÇİŞ NOKTASI<strong>${r.points.length}</strong></span><span data-user-content>${escapeText(rt("direct"))}<strong>${result.totalDist.toFixed(2)}<small>NM</small></strong></span><span data-user-content>A*<strong>—</strong></span></div><button class="btn secondary full" data-load-route="${escapeText(r.id)}">Seferi aç ${icon('arrow')}</button></div></article>`;}).join('')}</div>`:emptyLibrary(query?'Aradığınız sefer bulunamadı.':'Henüz kayıtlı sefer yok.',query?'Farklı bir sefer adı veya ay deneyin.':'Kaydettiğiniz rotalar burada görünür.','route','Sefer oluştur');}
else{const observations=d.observations.filter(p=>(p.month+' '+I18n.translate(p.month)+' '+p.lat+' '+p.lon+' '+RISK[pointModel(p.month,p.klor).level].label+' '+I18n.translate(RISK[pointModel(p.month,p.klor).level].label)).toLocaleLowerCase(I18n.locale).includes(query));$('libraryContents').innerHTML=observations.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Tarih</th><th>Konum</th><th>Ay</th><th>Klorofil-a</th><th>Risk sınıfı</th><th>İşlem</th></tr></thead><tbody>${observations.map(p=>`<tr><td>${stamp(p.createdAt)}</td><td class="mono">${p.lat.toFixed(3)} / ${p.lon.toFixed(3)}</td><td>${p.month}</td><td>${p.klor} mg/m³</td><td>${riskBadge(pointModel(p.month,p.klor).level)}</td><td><button class="table-action" data-observation="${escapeText(p.id)}">Aç ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:emptyLibrary(query?'Eşleşen gözlem yok.':'Henüz gözlem yok.',query?'Arama ölçütünüzü değiştirmeyi deneyin.':'Konum analizleriniz burada saklanır.','analysis','İlk gözlemini oluştur');}}
function emptyLibrary(title,description,page,label){return `<div class="library-empty"><span class="empty-emblem">${icon(page==='route'?'route':'radar')}</span><h2>${title}</h2><p>${description}</p><a href="#${page}" class="btn primary">${label} ${icon('arrow')}</a></div>`;}
function saveRoute(e){e.preventDefault();if(!$('saveForm').reportValidity())return;const name=$('saveName').value.trim();if(!name)return;try{const route=Workspace.saveRoute(state,name);state.name=route.name;state.routeId=route.id;renderRoute();updateCounts();$('saveDialog').close();notify('Seferiniz kaydedildi. Kayıtlarım bölümünden yeniden açabilirsiniz.');}catch(error){notify(error.message);}}
function download(content,type,name){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function fileStem(){return (state.name||'w-alerter-sefer').replace(/[^\p{L}\p{N} _-]/gu,'').trim().replace(/\s+/g,'-').slice(0,70)||'w-alerter-sefer';}
function exportJson(){const data=JSON.parse(Workspace.exportRoute(state));if(plannedRoute)data.computedRoute=plannedRoute;download(JSON.stringify(data,null,2),'application/json',fileStem()+'.json');notify('Rota JSON olarak indirildi. Bu dosyayı yeniden içe aktarabilirsiniz.');}
function exportGpx(){if(plannedRoute)return exportPlannedGpx();const xml=`<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="W-ALERTER" xmlns="http://www.topografix.com/GPX/1/1" xmlns:wa="https://w-alerter-ocean.sebnemnilozoglu.chatgpt.site/schema"><metadata><name>${escapeText(state.name)}</name><desc>W-ALERTER · ${I18n.translate(state.month)}</desc></metadata><rte><name>${escapeText(state.name)}</name>${state.points.map((p,i)=>`<rtept lat="${p.lat}" lon="${p.lon}"><name>${I18n.translate('Nokta '+(i+1))}</name><extensions><wa:chlorophyll>${p.klor}</wa:chlorophyll><wa:month>${state.month}</wa:month></extensions></rtept>`).join('')}</rte></gpx>`;download(xml,'application/gpx+xml',fileStem()+'.gpx');notify('Geçiş noktaları GPX olarak indirildi.');}
function exportHistory(){const all=Workspace.snapshot().observations;if(!all.length){notify('Henüz dışa aktarılacak gözlem yok.');return;}const rows=[['Tarih','Ay','Enlem','Boylam','Klorofil-a (mg/m3)','Referans','Oran','Risk','Model göstergesi (%)'],...all.map(p=>{const result=pointModel(p.month,p.klor);return[p.createdAt,p.month,p.lat,p.lon,p.klor,result.reference,result.ratio,RISK[result.level].label,result.rate];})];download('\ufeff'+rows.map(row=>row.map(v=>'"'+I18n.translate(String(v)).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8','w-alerter-gozlemler.csv');notify('Gözlem geçmişi CSV olarak indirildi.');}
async function importRoute(file){if(!file)return;if(file.size>2*1024*1024){notify('Dosya çok büyük. En fazla 2 MB boyutunda bir rota seçin.');return;}try{const route=Workspace.parseImport(await file.text()),previous={...state,points:pointCopy()};loadRoute(route);notify('Rota içe aktarıldı. Kaydetmek için seferinize bir ad verin.',()=>loadRoute(previous,previous.routeId));}catch(error){notify(error.message);}finally{$('routeImportFile').value='';}}
function init(){paintIcons();$('homeReferences').innerHTML=Object.entries(ARSIV).map(([month,value])=>`<div class="ribbon-value"><span>${month}</span><strong>${value.toFixed(4)}<small>mg/m³</small></strong></div>`).join('');$('archiveValues').innerHTML=Object.entries(ARSIV).map(([month,value],i)=>`<div class="archive-value-row"><span>0${i+1}</span><h3>${month}</h3><strong>${value.toFixed(4)}<small>mg/m³</small></strong><button data-archive-month="${month}" aria-label="${month} ayını analiz et">${icon('arrow-up')}</button></div>`).join('');updateReference();renderRoute();renderRecent();updateCounts();
$('analysisForm').addEventListener('submit',analyzePoint);$('analysisMonth').addEventListener('change',()=>{updateReference();invalidateAnalysis();});['analysisLat','analysisLon','analysisChlo'].forEach(id=>$(id).addEventListener('input',invalidateAnalysis));$('addAnalysisToRoute').addEventListener('click',()=>{if(!lastPoint)return;if(state.points.length>=1000){notify('Bir sefer en fazla 1000 nokta içerebilir.');return;}const p={...lastPoint};state.month=p.month;state.points.push({lat:p.lat,lon:p.lon,klor:p.klor});routeChanged();go('route');syncRouteMap();fitMap();notify('Gözleminiz rotaya geçiş noktası olarak eklendi.');});
$('routeName').addEventListener('input',()=>{state.name=$('routeName').value;persist();});$('routeName').addEventListener('blur',()=>{state.name=state.name.trim()||'İsimsiz sefer';$('routeName').value=state.name==='İsimsiz sefer'?'':state.name;persist();});$('routeMonth').addEventListener('change',()=>{state.month=$('routeMonth').value;routeChanged();});$('routeForm').addEventListener('submit',submitPoint);$('cancelEdit').addEventListener('click',()=>{cancelPointEdit();renderRoute();});$('routeList').addEventListener('click',e=>{const b=e.target.closest('[data-point-action]');if(b)pointAction(b.dataset.pointAction,Number(b.dataset.index));});$('analyzeRouteButton').addEventListener('click',analyzeRoute);$('clearRouteButton').addEventListener('click',()=>{const previous=pointCopy();state.points=[];cancelPointEdit();routeChanged();notify('Sefer taslağının noktaları temizlendi.',()=>{state.points=previous;routeChanged();});});
$('fitMapButton').addEventListener('click',fitMap);$('zoomInButton').addEventListener('click',()=>maps[currentMode]?.zoomIn());$('zoomOutButton').addEventListener('click',()=>maps[currentMode]?.zoomOut());document.querySelectorAll('[data-layer]').forEach(b=>b.addEventListener('click',()=>setMapLayer(currentMode,b.dataset.layer)));
$('saveRouteButton').addEventListener('click',()=>{if(state.points.length<2)return;$('saveName').value=state.name==='İsimsiz sefer'?'':state.name;$('saveDialog').showModal();});$('saveForm').addEventListener('submit',saveRoute);document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));$('helpButton').addEventListener('click',()=>$('helpDialog').showModal());$('helpDone').addEventListener('click',()=>$('helpDialog').close());$('mobileMenuButton').addEventListener('click',()=>{const open=$('mainNav').classList.toggle('open');$('mobileMenuButton').setAttribute('aria-expanded',String(open));});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('mainNav').classList.remove('open');$('mobileMenuButton').setAttribute('aria-expanded','false');}});
$('toastAction').addEventListener('click',()=>{const action=undoAction;$('toast').hidden=true;undoAction=null;clearTimeout(toastTimer);if(action)action();});$('importRouteButton').addEventListener('click',()=>$('routeImportFile').click());$('routeImportFile').addEventListener('change',e=>importRoute(e.target.files[0]));$('exportJsonButton').addEventListener('click',exportJson);$('exportGpxButton').addEventListener('click',exportGpx);$('exportReportButton').addEventListener('click',exportReport);$('exportHistoryButton').addEventListener('click',exportHistory);
$('newRouteButton').addEventListener('click',e=>{e.preventDefault();const previous={...state,points:pointCopy()};loadRoute({name:'İsimsiz sefer',month:state.month,points:[]});notify('Yeni bir sefer taslağı hazır.',()=>loadRoute(previous,previous.routeId));});document.querySelectorAll('[data-library-tab]').forEach(b=>b.addEventListener('click',()=>{libraryTab=b.dataset.libraryTab;$('librarySearch').value='';renderLibrary();}));$('librarySearch').addEventListener('input',renderLibrary);
document.addEventListener('click',e=>{const observation=e.target.closest('[data-observation]');if(observation)reopenObservation(observation.dataset.observation);const load=e.target.closest('[data-load-route]');if(load){const route=Workspace.snapshot().routes.find(r=>r.id===load.dataset.loadRoute);if(route)loadRoute(route,route.id);}const remove=e.target.closest('[data-delete-route]');if(remove){const route=Workspace.snapshot().routes.find(r=>r.id===remove.dataset.deleteRoute);if(route&&Workspace.removeRoute(route.id)){renderLibrary();notify('Kaydedilen sefer kaldırıldı.',()=>{try{Workspace.saveRoute({...route,routeId:route.id},route.name);renderLibrary();}catch(error){notify(error.message);}});}else notify('Sefer silinemedi. Tarayıcı depolamasını kontrol edin.');}const month=e.target.closest('[data-archive-month]');if(month){$('analysisMonth').value=month.dataset.archiveMonth;updateReference();invalidateAnalysis();go('analysis');}});
window.addEventListener('languagechange',()=>{renderRoute();renderRecent();updateReference();if(currentPage==='library')renderLibrary();if(lastPoint)displayAnalysis(lastPoint,false,false);syncRouteMap();if(plannedRoute)renderRouteOutput();const titles={home:'Deniz ekosistemi için rota analizi',analysis:'Konum analizi',route:'Rota planlayıcı',library:'Kayıtlarım',archive:'Veri & yöntem',data:'Veri merkezi',ocean:'Kuzey Atlantik',species:'Tür modelleri',hydra:'HYDRA 2.0',fuel:'Yakıt & karbon',voyage:'Sefer karşılaştırması'};document.title=titles[currentPage]+' — W-ALERTER';});window.addEventListener('hashchange',()=>showPage(location.hash.slice(1)));showPage(location.hash.slice(1)||'home');}
function exportReport(){if(state.points.length<2)return;if(plannedRoute)return exportPlannedReport();const result=routeModel(state.points,state.month),created=stamp(new Date().toISOString());const rows=state.points.map((p,i)=>{const risk=routePointStatus(state.month,p.klor)==='RISKLI',distance=i?calculateDistance(state.points[i-1].lat,state.points[i-1].lon,p.lat,p.lon):0;return `<tr><td>${i+1}</td><td>${p.lat.toFixed(5)}</td><td>${p.lon.toFixed(5)}</td><td>${p.klor}</td><td>${i?distance.toFixed(2):'—'}</td><td>${risk?'Riskli':'Normal'}</td></tr>`;}).join('');const report=`<!doctype html><html lang="tr"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title data-user-content>${escapeText(state.name)} — ${I18n.translate('W-ALERTER Sefer Raporu')}</title><style>*{box-sizing:border-box}body{margin:0;background:#eeeee6;color:#183b35;font:14px/1.7 system-ui,sans-serif}.sheet{max-width:960px;margin:40px auto;background:white;padding:50px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid #183b35;padding-bottom:24px;font-size:12px;color:#60788a}.brand{display:block;width:112px;height:auto;background:#fff}h1{font-size:38px;letter-spacing:-1.5px;line-height:1.3;margin:35px 0 12px;overflow-wrap:anywhere}h2{font-size:22px;font-weight:500;margin-top:35px}.caption{color:#657c8e;font-size:12px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;background:#eef3e3;padding:25px;margin:32px 0}.stats span{display:block;font-size:10px;color:#526d80}.stats strong{display:block;font-size:28px;font-weight:500;letter-spacing:-1px;margin-top:7px}.stats small{font-size:12px;font-weight:400;margin-left:5px;color:#6f8798}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left}th,td{padding:13px 9px;border-bottom:1px solid #dce5ed}th{font-weight:400;color:#526d80;background:#f0f1e7}footer{border-top:1px solid #dce5ed;padding-top:20px;margin-top:35px;font-size:10px;color:#60788a}.note{font-size:12px;color:#526d80}.tools{max-width:960px;margin:20px auto;text-align:right}button{border:0;background:#183b35;color:white;padding:12px 18px;border-radius:4px;cursor:pointer}@media(max-width:650px){.sheet{margin:15px;padding:25px}h1{font-size:29px}header{gap:20px}.stats{padding:16px;gap:10px}.stats strong{font-size:22px}.table{overflow:auto}table{white-space:nowrap}.tools{margin:15px}}@media print{body{background:white}.sheet{margin:0;padding:15px}.tools{display:none}}</style><div class="tools"><button onclick="window.print()">Yazdır / PDF olarak kaydet</button></div><article class="sheet"><header><img class="brand" src="${BRAND_LOGO}" alt="W-ALERTER"><span>SEFER ANALİZ RAPORU<br>${escapeText(created)}</span></header><h1 data-user-content>${escapeText(state.name)}</h1><p class="caption">Antarktika · ${state.month} dönemi · ${state.points.length} geçiş noktası</p><div class="stats"><div><span>TOPLAM MESAFE</span><strong>${result.totalDist.toFixed(2)}<small>NM</small></strong></div><div><span>RİSKLİ MESAFE</span><strong>${result.riskDist.toFixed(2)}<small>NM</small></strong></div><div><span>KLASİK YAKIT GÖSTERGESİ</span><strong>${result.fuelSaving.toFixed(1)}<small>L</small></strong></div></div><h2>Geçiş noktaları ve etaplar</h2><div class="table"><table><thead><tr><th>Nokta</th><th>Enlem</th><th>Boylam</th><th>Klorofil-a (mg/m³)</th><th>Önceki etap (NM)</th><th>Nokta riski</th></tr></thead><tbody>${rows}</tbody></table></div><h2>Veri ve yöntem</h2><p class="note">${state.month} klorofil-a referansı: <strong>${ARSIV[state.month].toFixed(4)} mg/m³</strong> · NASA MODIS-Aqua, W-ALERTER referans arşivi. Geçiş noktası oranı 1.25 ve üzerindeyse riskli kabul edilir. Etabın risk durumu varış noktasına göre hesaplanır.</p><p class="note">Mesafe: Haversine, R = 3440 NM. Yakıt tasarrufu tahmini: riskli mesafe × 2.5 L/NM. Modelin hedef hız parametresi 10 knot, yavaşlama oranı %28.5’tir. Rota, girilen noktaları sırasıyla birleştirir.</p><p class="note">Klasik göstergeler doğrulanmış tür olasılığı, gemiye özgü yakıt tüketimi veya CO₂ hesabı değildir. NASA ham ürün dosyası, yıl aralığı ve kesin kapsam sağlanmamıştır.</p><footer>W-ALERTER / MARINE INTELLIGENCE · Bu rapor kullanıcı ölçümleri ve mevcut W-ALERTER modeli ile üretilmiştir.</footer></article></html>`;download(I18n.translateHTML(report),'text/html;charset=utf-8',fileStem()+'-rapor.html');notify('Sefer raporu indirildi. Raporu açıp PDF olarak da kaydedebilirsiniz.');}
let homeMap=null;function initHomeMap(){if(homeMap||!window.L)return;homeMap=L.map('homeMap',{zoomControl:false,dragging:false,touchZoom:false,doubleClickZoom:false,scrollWheelZoom:false,keyboard:false,boxZoom:false}).setView([42,-40],3);makeLayer('ocean').addTo(homeMap);requestAnimationFrame(()=>homeMap.invalidateSize());}
if(typeof window!=='undefined')window.WALegacy=Object.freeze({references:ARSIV,pointModel,routeModel,calculateDistance,routePointStatus,getDraft:()=>({...Workspace.snapshot().draft,computedRoute:plannedRoute}),getPlannedRoute:()=>plannedRoute?JSON.parse(JSON.stringify(plannedRoute)):null});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();

function exportPlannedGpx(){const r=plannedRoute,xml=`<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="W-ALERTER" xmlns="http://www.topografix.com/GPX/1/1"><metadata><name>${escapeText(state.name)}</name><desc>${escapeText(rt('engine')+' · '+rt('limit'))}</desc></metadata><trk><name>${escapeText(state.name)}</name><desc>${escapeText(r.engineVersion+' · '+r.topologyId+' · '+r.topologySha256)}</desc><trkseg>${r.coordinates.map(([lon,lat])=>`<trkpt lat="${lat}" lon="${lon}"/>`).join('')}</trkseg></trk></gpx>`;download(xml,'application/gpx+xml',fileStem()+'-astar.gpx');}
function exportPlannedReport(){const r=plannedRoute,body=`<!doctype html><html lang="${I18n.language}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>W-ALERTER · ${escapeText(state.name)}</title><style>body{font:14px/1.8 system-ui;color:#23414b;margin:40px auto;padding:25px;max-width:900px}h1{font-size:32px}table{width:100%;border-collapse:collapse}td,th{padding:14px 8px;border-bottom:1px solid #dce6e8;text-align:left}small{overflow-wrap:anywhere}.stats{display:flex;gap:35px;margin:35px 0}.stats strong{display:block;font-size:27px}details{margin:25px 0}button{padding:10px 15px}@media print{button{display:none}}</style><button onclick="print()">${escapeText(I18n.translate('Yazdır / PDF olarak kaydet'))}</button><p>W-ALERTER · ${escapeText(rt('engine'))}</p><h1>${escapeText(state.name)}</h1><p>${escapeText(rt('limit'))}</p><div class="stats"><div>${escapeText(rt('distance'))}<strong>${r.totalNM.toFixed(2)} NM</strong></div><div>${escapeText(rt('direct'))}<strong>${r.directNM.toFixed(2)} NM</strong></div></div><table><thead><tr><th>#</th><th>LAT / LON</th><th>NM</th><th>A*</th></tr></thead><tbody>${r.legs.map((l,i)=>`<tr><td>${i+1} → ${i+2}</td><td>${state.points[i+1].lat} / ${state.points[i+1].lon}</td><td>${l.distanceNM.toFixed(2)}</td><td>${escapeText(rt('leg'))}</td></tr>`).join('')}</tbody></table><p>${escapeText(rt('biology'))}</p><h2>${escapeText(rt('source'))}</h2><p>${escapeText(rt('method'))}</p><small>${escapeText(r.engineVersion)}<br>${escapeText(r.topologyId)}<br>SHA-256 ${escapeText(r.topologySha256)}</small><p>Made with Natural Earth · public domain · land 5.1.1 / ice shelves 4.1.0</p></html>`;download(body,'text/html;charset=utf-8',fileStem()+'-astar-rapor.html');}
